const brands = [
  {
    brand: 'dax-collective',
    agentId: 'dax_collective_data_collection_agent',
    focus: ['company structure', 'parent site', 'cross-brand routing', 'shared assets']
  },
  {
    brand: 'dax-the-traveler',
    agentId: 'dax_the_traveler_data_collection_agent',
    focus: ['travel video ideas', 'destination pages', 'YouTube channel setup', 'short-form clips']
  },
  {
    brand: 'time-zone-travelers',
    agentId: 'time_zone_travelers_data_collection_agent',
    focus: ['itineraries', 'trip templates', 'packing lists', 'lead magnets']
  },
  {
    brand: 'ani-dax',
    agentId: 'ani_dax_data_collection_agent',
    focus: ['anime commentary ideas', 'community prompts', 'merch concepts', 'sticker designs']
  },
  {
    brand: 'gods-vessel',
    agentId: 'gods_vessel_data_collection_agent',
    focus: ['devotional themes', 'scripture references', 'encouragement posts', 'faith merch']
  }
];

return brands.map((entry) => ({
  json: {
    ...entry,
    reviewStatus: 'manual_review_required',
    publishAllowed: false,
    collectionMode: 'manual_first',
    requiredInventories: [
      'existing_pages',
      'social_accounts_needed',
      'content_assets',
      'video_pipeline_inputs',
      'merch_and_sticker_inputs',
      'credential_gaps_without_secret_values'
    ],
    createdAt: new Date().toISOString()
  }
}));

return $input.all().map((item) => {
  const brand = item.json.brand;
  const focus = item.json.focus || [];
  return {
    json: {
      ...item.json,
      collectionTasks: [
        `List existing files, pages, workflows, and assets for ${brand}`,
        `Identify missing account/page/channel setup needed for ${brand}`,
        `Prepare starter video, post, itinerary, merch, and sticker input requirements for ${brand}`,
        `Record blockers without copying or exposing credentials for ${brand}`,
        `Send a manual review summary before any publishing is enabled for ${brand}`
      ],
      researchQuestions: focus.map((topic) => `What usable existing material or missing input exists for ${brand}: ${topic}?`),
      handoffTarget: 'DAX-04 Company Startup Operator - Manual Review',
      qaChecks: [
        'no_secrets_collected',
        'existing_workflows_checked_first',
        'brand_specific_outputs_named',
        'manual_review_required',
        'publish_disabled'
      ]
    }
  };
});

const items = $input.all();
return [{
  json: {
    agentId: 'dax_collective_data_collection_agent',
    status: 'ready_for_manual_collection',
    reviewStatus: 'manual_review_required',
    publishAllowed: false,
    brandsQueued: items.map((item) => item.json.brand),
    brandCount: items.length,
    nextAction: 'Open each brand item, collect missing non-secret inputs, and route reviewed summaries into the startup operator.',
    accountSetupStillManual: ['TikTok accounts', 'Instagram accounts', 'Facebook pages', 'YouTube channels/OAuth', 'public n8n callback URL'],
    secretHandling: 'Use n8n credentials or platform consoles only. Do not paste secrets into workflow JSON or project files.',
    items
  }
}];
